.home_grid_view .elementor-widget-container{
	 clear: both;
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    -ms-flex-wrap: wrap;
    flex-wrap: wrap;
    margin-left: -15px;
    margin-right: -15px;
    padding: 0;
}

.home_grid_view .elementor-widget-container .tutor-widget-course-loop {
	width: 30.5%;
}

